pub enum CertifyError {
    ReportNotJson,
    ReportNotObject,
}

fn sha256_hex(text: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    hex::encode(hasher.finalize())
}

pub fn certification_event(
    report_path: &Path,
    report_text: &str,
    exit_code: i32,
    actor: Actor,
    timestamp: DateTime<Utc>,
) -> Result<EventInput, CertifyError> {
    let report: Value = serde_json::from_str(report_text).map_err(|_| CertifyError::ReportNotJson)?;
    let obj = report.as_object().ok_or(CertifyError::ReportNotObject)?;

    let pack_versions: Vec<String> = obj
        .get("packs")
        .and_then(|p| p.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|p| {
                    let name = p.get("name")?.as_str()?;
                    let version = p.get("version")?.as_str()?;
                    Some(format!("{name}/{version}"))
                })
                .collect()
        })
        .unwrap_or_default();

    let finding_count = obj
        .get("findings")
        .and_then(|f| f.as_array())
        .map(|a| a.len())
        .unwrap_or(0);

    let tool_version = obj
        .get("tool")
        .and_then(|t| t.get("version"))
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();

    let golden_baseline = obj
        .get("golden_baseline")
        .and_then(|g| g.as_str())
        .unwrap_or("")
        .to_string();

    let doc_id = report_path
        .file_stem()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default();

    let details = json!({
        "report_path": report_path.to_string_lossy(),
        "report_hash": sha256_hex(report_text),
        "pack_versions": pack_versions,
        "content_hashes": obj.get("content_hashes").cloned().unwrap_or(json!({})),
        "finding_count": finding_count,
        "exit_code": exit_code,
        "tool_version": tool_version,
        "golden_baseline": golden_baseline,
    });

    let verification_result = json!({
        "exit_code": exit_code,
        "findings": finding_count,
        "total": finding_count,
    });

    Ok(EventInput {
        event_id: uuid::Uuid::new_v4().to_string(),
        event_type: "certification_completed".to_string(),
        timestamp,
        actor,
        details: Some(details),
        doc_id,
        prev_hash: None,
        event_class: Some("record_only".to_string()),
        verification_result: Some(verification_result),
        session_id: None,
        identity_hash: None,
    })
}

pub struct Actor {
    /// 操作者标识，须为合法的人类标识或确定性程序标识。
    pub actor_id: String,
    /// 操作者类型：human、agent、system。
    /// agent 须对应确定性程序调用的执行者，非 LLM 直接调用。
    #[serde(deserialize_with = "deserialize_actor_type")]
    pub actor_type: ActorType,
    /// 调用途径，标识操作者通过何种方式触发此事件。
    pub invoked_via: String,
}

pub enum ActorType {
    Human,
    Agent,
    System,
}

fn deserialize_actor_type<'de, D>(deserializer: D) -> Result<ActorType, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let s = String::deserialize(deserializer)?;
    match s.to_lowercase().as_str() {
        "human" => Ok(ActorType::Human),
        "agent" => Ok(ActorType::Agent),
        "system" => Ok(ActorType::System),
        _ => Err(serde::de::Error::custom(format!(
            "invalid actor_type: {s}, expected human/agent/system"
        ))),
    }
}

pub struct Event {
    // 必须字段
    /// 事件全局唯一标识，UUID v4 格式。
    pub event_id: String,
    /// 事件类型标识，取值见 SPEC-004#event-type-hierarchy。
    pub event_type: String,
    /// ISO 8601 格式时间戳，事件流内单调递增。
    pub timestamp: DateTime<Utc>,
    /// 操作者子结构。
    pub actor: Actor,
    /// 事件负载，JSON 对象。部分事件类型允许省略。
    #[serde(default)]
    pub details: Option<JsonValue>,
    /// 关联文档标识，跨事件串联同一治理对象的生命周期。
    pub doc_id: String,
    /// 前事件哈希，首事件取全零值。
    pub prev_hash: String,
    /// 本事件哈希，由本事件除 event_hash 外的全部字段计算得出。
    pub event_hash: String,
    // 可选字段
    /// 事件分类：consumable 或 record_only，承接 SPEC-004#event-classification。
    #[serde(default)]
    pub event_class: Option<String>,
    /// 校验结果，部分事件类型承载。
    #[serde(default)]
    pub verification_result: Option<JsonValue>,
    /// 链上正身绑定（idenlane-solo iden-01）：事件信封所载会话标识。
    /// 租约笔承载会话号；直改笔为空或直改标记。旧事件行缺省即 None，
    /// 零数据迁移零改动，verify 重算兼容（新增字段只出现在新行）。
    #[serde(default)]
    pub session_id: Option<String>,
    /// 链上正身绑定（idenlane-solo iden-01）：生产者身份哈希。
    /// 租约笔按会话号从台账查得；直改笔按身份件查得。旧事件行缺省即 None。
    #[serde(default)]
    pub identity_hash: Option<String>,
}

pub struct EventInput {
    pub event_id: String,
    pub event_type: String,
    pub timestamp: DateTime<Utc>,
    pub actor: Actor,
    pub details: Option<JsonValue>,
    pub doc_id: String,
    /// 可选，调用方若已计算则传入；否则由 append 内部填充。
    pub prev_hash: Option<String>,
    /// 可选事件分类，缺省 None 即不入分类字段，三问意图事件固定 record_only。
    pub event_class: Option<String>,
    /// 可选校验结果，承 SPEC-006 报告消费入口透传，缺省 None。
    pub verification_result: Option<JsonValue>,
    /// 链上正身绑定写入（idenlane-solo iden-01）：会话号与生产者身份
    /// 哈希，追加时由调用方按会话台账或直改身份件解析后填入，None 即旧
    /// 行为零改动。
    pub session_id: Option<String>,
    pub identity_hash: Option<String>,
}

impl Event {
    /// 将 Event 反序列化为 JSON 行（单行 NDJSON 格式）。
    pub fn to_json_line(&self) -> Result<String, serde_json::Error> {
        serde_json::to_string(self)
    }

    /// 从 JSON 行解析 Event。
    pub fn from_json_line(line: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(line)
    }
}

pub fn to_json_line(&self) -> Result<String, serde_json::Error> {
        serde_json::to_string(self)
    }

pub fn from_json_line(line: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(line)
    }

