            timestamp: Utc.timestamp_opt(1000000 + hour as i64 * 3600, 0).unwrap(),
            actor: Actor {
                actor_id: actor_id.into(),
                actor_type: ActorType::Agent,
                invoked_via: "test".into(),
            },
            details: Some(serde_json::json!({"change_summary": "test"})),
