            prev_hash: "0".into(),
            event_hash: "0".into(),
            event_class: None,
            verification_result: None,
            session_id: None,
            identity_hash: None,
        }
    }

    fn store() -> Vec<Event> {
        vec![
            make_event("e1", "task_completion", "agent-1", 10),
            make_event("e2", "session_open", "agent-1", 11),
            make_event("e3", "task_completion", "agent-2", 12),
            make_event("e4", "crosscheck_completed", "agent-1", 13),
        ]
    }

