        let events = store();
        let filter = EventFilter {
            event_type: Some("task_completion".into()),
            ..Default::default()
        };
        let result = query(&events, Some(filter), None);
        assert_eq!(result.total, 2);
        assert!(result.events.iter().all(|e| e.event_type == "task_completion"));
    }

