fn t1_golden_vectors_recompute() {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("fixtures/golden/event-stream-vectors.json");
        let text = std::fs::read_to_string(&path).expect("向量集存在");
