        assert!(vectors.len() >= 5, "五类边界至少五向量");
        let mut classes = std::collections::HashSet::new();
        for v in &vectors {
            let event: Event = serde_json::from_value(v["event"].clone()).unwrap();
            classes.insert(v["class"].as_str().unwrap().to_string());
